insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_4_v1'
from (values
('128.5.a.7',3,'Why does learning to read in Spanish help a student learn to read in English?','["Many literacy skills transfer between the two languages", "Only spelling is shared", "The two languages share no skills", "Reading in one language erases the other"]'::jsonb,0,'Skills such as decoding, comprehension and vocabulary strategies carry over between languages.','original'),
('128.5.a.7',3,'Research on second language acquisition says that students learn best when language lessons are:','["separated from all other skills", "connected to reading, writing, listening and speaking", "limited to memorizing lists", "taught only through silent copying"]'::jsonb,1,'Language is learned through meaningful use across all four skills.','original'),
('128.5.b.1.A',2,'Active listeners ask relevant questions to:','["interrupt the speaker", "tease a classmate", "clarify information", "change the subject"]'::jsonb,2,'Relevant questions make the speaker''s meaning clearer.','original'),
('128.5.b.1.A',3,'Which is a pertinent comment during a class discussion about a story?','["What time is lunch?", "Can I get a drink of water?", "I like pizza.", "I agree with Mia because her example matched the text."]'::jsonb,3,'A pertinent comment connects to the topic and to what others said.','original'),
('128.5.b.1.B',2,'To restate directions you were given, you:','["say them again in your own words", "ignore the first step", "repeat only the last word", "guess what comes next"]'::jsonb,0,'Restating shows you understood the series of steps.','original'),
('128.5.b.1.B',3,'When you give oral instructions with several steps, you should:','["mix up the order", "say them in order with clear signal words", "whisper so no one hears", "skip the hard steps"]'::jsonb,1,'Related sequences of instructions need a clear order.','original'),
('128.5.b.1.C',3,'Speaking coherently about a topic includes:','["looking at the floor and mumbling", "jumping to new topics", "staying on topic with a clear voice and eye contact", "talking in a rush"]'::jsonb,2,'Coherent speakers use eye contact, rate and volume to keep listeners with them.','original'),
('128.5.b.1.C',2,'A speaker who looks at the audience is showing that they:','["forgot the topic", "are bored", "are lost", "are engaging the listeners"]'::jsonb,3,'Eye contact helps hold the audience''s attention.','original'),
('128.5.b.1.D',2,'Agreed-upon discussion rules help a group:','["work well together", "finish faster by talking over others", "ignore teammates", "avoid every new idea"]'::jsonb,0,'Rules, norms and protocols make teamwork fair and productive.','original'),
('128.5.b.1.D',2,'A protocol for sharing ideas in a group could be to:','["shout out answers", "raise a hand and wait your turn", "talk the whole time", "leave the group"]'::jsonb,1,'Taking turns follows agreed-upon group norms.','original'),
('128.5.b.1.E',2,'Conversing politely in all situations includes:','["teasing others", "ignoring greetings", "saying please and thank you", "interrupting often"]'::jsonb,2,'Polite social communication shows respect.','original'),
('128.5.b.1.E',3,'When you disagree with a classmate politely, you might say:','["That is a dumb idea.", "Be quiet.", "You are wrong and I am right.", "I see it differently because of this detail."]'::jsonb,3,'Polite disagreement gives a reason without insulting anyone.','original'),
('128.5.b.10.A',2,'A news article explains how a new bridge was built. The author''s purpose is to:','["inform", "scare", "sing", "tease"]'::jsonb,0,'Informational articles are written to give facts.','original'),
('128.5.b.10.A',2,'An author writes a funny tale about a clumsy robot. The author''s purpose is mainly to:','["sell a product", "entertain", "give directions", "teach a science process"]'::jsonb,1,'Humorous stories are written to entertain readers.','original'),
('128.5.b.10.B',3,'An author tells events in time order. This text structure helps the reader:','["learn spelling rules", "see opposite meanings", "follow what happened first, next and last", "find rhyming words"]'::jsonb,2,'Chronological structure supports understanding of a sequence of events.','original'),
('128.5.b.10.B',3,'A text describes a problem and then ways to fix it. The structure helps the author:','["spell names", "count syllables", "list opposite words", "show how the problem can be solved"]'::jsonb,3,'Problem and solution structure supports the author''s purpose of explaining solutions.','original'),
('128.5.b.10.C',2,'A heading in an article helps the reader:','["see what a section is about", "count the pages", "know who printed it", "find rhymes"]'::jsonb,0,'Headings are print features that organize information.','original'),
('128.5.b.10.C',3,'A photograph with a caption is a graphic feature that:','["removes the topic", "adds details to the words", "spells hard words", "lists the author''s pets"]'::jsonb,1,'Graphics and captions give extra information.','original'),
('128.5.b.10.D',3,'Which sentence has a simile?','["The runner ran home.", "Lightning struck.", "The runner was as fast as lightning.", "The runner was fast."]'::jsonb,2,'A simile compares two things using as or like.','original'),
('128.5.b.10.D',3,'''The classroom was a zoo'' is an example of a:','["rhyme", "simile", "fact", "metaphor"]'::jsonb,3,'A metaphor says one thing is another without using like or as.','original'),
('128.5.b.10.E',3,'A narrator who says ''I'' and ''we'' tells the story from:','["first-person point of view", "no point of view", "third-person point of view", "second-person point of view"]'::jsonb,0,'First-person narrators use I and we.','original'),
('128.5.b.10.E',3,'''She looked out the window while he cooked'' is told from:','["second-person point of view", "third-person point of view", "first-person point of view", "a poem''s point of view"]'::jsonb,1,'Third-person narrators use she, he and they.','original'),
('128.5.b.10.F',3,'An author''s voice is shown by:','["the index", "paper color", "word choice and style that sound unique", "page numbers"]'::jsonb,2,'Voice is the personality in the author''s language.','original'),
('128.5.b.10.F',3,'Which sentence shows a playful voice?','["Brother sleeps.", "He is asleep.", "The man slept.", "My brother snores like a grumpy bear in a cave!"]'::jsonb,3,'Humor and vivid comparison create voice.','original'),
('128.5.b.10.G',3,'Hyperbole is:','["extreme exaggeration for effect", "a true fact", "a repeated sound", "a comparison using like"]'::jsonb,0,'Hyperbole is not meant to be taken literally.','original'),
('128.5.b.11.A',3,'When planning a first draft, the genre you choose depends on:','["the color of your paper", "your topic, purpose and audience", "the weight of your pencil", "today''s date"]'::jsonb,1,'Writers choose a genre to fit topic, purpose and audience.','original'),
('128.5.b.11.A',2,'A graphic organizer such as a web helps a writer:','["edit spelling at the end only", "publish the draft", "plan and group ideas before drafting", "print the title"]'::jsonb,2,'Planning tools organize ideas first.','original'),
('128.5.b.11.B.i',3,'Which part of an essay wraps up the main idea at the end?','["the caption", "the title", "the heading", "the conclusion"]'::jsonb,3,'A purposeful structure ends with a conclusion.','original'),
('128.5.b.11.B.i',3,'An introduction should:','["get the reader''s attention and name the topic", "repeat the conclusion", "list every detail", "end the essay"]'::jsonb,0,'The introduction opens the piece and states what it is about.','original'),
('128.5.b.11.B.ii',3,'Which detail fits a paragraph about why dogs make good pets?','["Fish live in water.", "Dogs are loyal and love to play.", "Cats have whiskers.", "Cars have wheels."]'::jsonb,1,'Relevant details support the idea.','original'),
('128.5.b.11.B.ii',3,'To make a writing idea engaging, a writer can add:','["extra blank spaces", "unrelated facts", "vivid details that fit the topic", "repeated sentences"]'::jsonb,2,'Engaging ideas use relevant, interesting details.','original'),
('128.5.b.11.C',3,'Combining two short, choppy sentences into one is a revision for:','["handwriting", "the title", "margins", "sentence structure"]'::jsonb,3,'Combining sentences improves how sentences flow.','original'),
('128.5.b.11.C',2,'Replacing the word ''nice'' with ''friendly'' improves:','["word choice", "margins", "handwriting", "page length"]'::jsonb,0,'A more precise word improves word choice.','original'),
('128.5.b.11.D.i',3,'Which Spanish sentence agrees in number between the subject and the verb?','["El niño juegan afuera.", "Los niños juegan afuera.", "Los niños juega afuera.", "Los niño juega afuera."]'::jsonb,1,'A plural subject takes a plural verb.','original'),
('128.5.b.11.D.i',3,'A compound sentence joins:','["two periods", "two titles", "two complete thoughts with a conjunction", "two fragments with no verb"]'::jsonb,2,'Compound sentences combine independent clauses.','original'),
('128.5.b.11.D.ii',4,'Which sentence is in the imperfect past?','["Ayer jugué en el parque.", "Mañana jugaré en el parque.", "Hoy juego en el parque.", "Cuando era niña, jugaba en el parque."]'::jsonb,3,'Jugaba shows a repeated or ongoing action in the past.','original'),
('128.5.b.11.D.ii',4,'In ''Ella ha comido'', the verb phrase ha comido is in the:','["present perfect, using a past participle", "simple present", "command form", "future tense"]'::jsonb,0,'Haber plus a past participle forms a perfect tense.','original'),
('128.5.b.11.D.iii',3,'Which pair uses the correct gender-specific articles?','["el casa, la libro", "la casa, el libro", "el casa, el libro", "la casa, la libro"]'::jsonb,1,'Casa is feminine and libro is masculine.','original'),
('128.5.b.11.D.iii',2,'Which noun is plural?','["libro", "ciudad", "mariposas", "mariposa"]'::jsonb,2,'Plural nouns commonly end in -s.','original'),
('128.5.b.11.D.iv',3,'Which sentence uses a comparative?','["Mi perro es el más grande de todos.", "Mi perro es grande.", "Mi perro corre.", "Mi perro es más grande que tu perro."]'::jsonb,3,'Más plus que compares two things.','original'),
('128.5.b.11.D.iv',3,'''El más alto de la clase'' is a:','["superlative", "preposition", "verb", "comparative"]'::jsonb,0,'A superlative names the highest degree in a group.','original'),
('128.5.b.11.D.v',3,'Which adverb tells how an action is done (manner)?','["ayer", "rápidamente", "hoy", "mañana"]'::jsonb,1,'Adverbs ending in -mente often show manner.','original'),
('128.5.b.11.D.v',3,'Which adverb tells when (time)?','["despacio", "bien", "después", "fuerte"]'::jsonb,2,'Después means afterward.','original'),
('128.5.b.11.D.vi',3,'A prepositional phrase begins with a preposition and ends with:','["an adjective only", "a period only", "a verb", "a noun or pronoun"]'::jsonb,3,'The object of the preposition is a noun or pronoun.','original'),
('128.5.b.11.D.vii',3,'Which pronoun fits: Yo ___ lavo las manos?','["me", "se", "le", "te"]'::jsonb,0,'Me is the reflexive pronoun that matches yo.','original'),
('128.5.b.11.D.vii',3,'Which word shows who owns the book?','["por", "mi", "sin", "al"]'::jsonb,1,'Mi is a possessive word meaning my.','original'),
('128.5.b.11.D.viii',3,'The word ''pero'' in ''Quiero ir, pero llueve'' joins:','["two numbers", "two titles", "two complete thoughts into one sentence", "two syllables"]'::jsonb,2,'Coordinating conjunctions can form compound sentences.','original'),
('128.5.b.11.D.viii',3,'A compound subject is:','["a verb with no subject", "one subject with two verbs", "a title with a subject", "two or more subjects sharing one verb"]'::jsonb,3,'Conjunctions can join subjects.','original'),
('128.5.b.11.D.ix',2,'Which word should start with a capital letter?','["México", "ciudad", "país", "estado"]'::jsonb,0,'Names of countries are proper nouns.','original'),
('128.5.b.11.D.ix',3,'Which name of a historical event should be capitalized?','["el recreo", "la Revolución Mexicana", "la comida", "la fiesta"]'::jsonb,1,'Historical period and event names are capitalized.','original'),
('128.5.b.11.D.x',3,'Which sentence uses commas in a series correctly?','["Compré manzanas, peras, y, uvas.", "Compré, manzanas peras y uvas.", "Compré manzanas, peras y uvas.", "Compré manzanas peras, y uvas."]'::jsonb,2,'Commas separate items in a series.','original'),
('128.5.b.11.D.x',3,'Which date is punctuated correctly?','["Monday May 5, 2025,", "Monday May, 5 2025", "Monday, May 5 2025", "Monday, May 5, 2025"]'::jsonb,3,'Use a comma after the day of the week and between the day and year.','original'),
('128.5.b.11.D.xi',3,'Which spelling names the farm animal that gives wool?','["oveja", "obeja", "ovega", "ovexa"]'::jsonb,0,'Oveja is spelled with v and j.','original'),
('128.5.b.11.D.xi',3,'Which spelling names the number between nine and eleven?','["dies", "diez", "diéz", "diés"]'::jsonb,1,'Diez ends in z.','original'),
('128.5.b.11.E',2,'Publishing written work means:','["erasing your plan", "tearing the page", "sharing a final copy with an audience", "starting a rough draft"]'::jsonb,2,'Publishing presents polished writing to readers.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_4_v1'
from (values
('128.5.b.11.E',2,'Which is a way to publish a story for classmates?','["tearing it up", "leaving it blank", "hiding the paper in a desk", "posting a clean final copy on a bulletin board"]'::jsonb,3,'Posting or reading a final copy shares the work.','original'),
('128.5.b.12.A',2,'Personal narratives are written from the author''s:','["own real experience", "recipe", "map", "dictionary"]'::jsonb,0,'A personal narrative tells about the writer''s own life.','original'),
('128.5.b.12.A',3,'Poetry often uses:','["numbered steps", "line breaks and sound devices", "footnotes only", "tables of data"]'::jsonb,1,'Poems use lines, rhythm and sound.','original'),
('128.5.b.12.B',3,'A brief informational composition should include:','["only opinions", "only dialogue", "a main idea supported by facts", "only rhymes"]'::jsonb,2,'Informational writing explains with facts.','original'),
('128.5.b.12.B',3,'Which sentence best begins an informational composition about owls?','["Once there was a dragon.", "I like my pillow.", "Buy owls today!", "Owls are birds that hunt at night."]'::jsonb,3,'A topic sentence states the subject with a fact.','original'),
('128.5.b.12.C',3,'An opinion essay should state:','["a claim and reasons that support it", "only a list of rhymes", "only a title", "only a drawing"]'::jsonb,0,'Argumentative texts need a claim and reasons.','original'),
('128.5.b.12.C',3,'Which reason supports the claim ''Our class should have a garden''?','["Gardens are green.", "Plants teach students how living things grow.", "I have a shirt.", "Today is Monday."]'::jsonb,1,'A reason connects directly to the claim.','original'),
('128.5.b.12.D',2,'A thank-you note usually includes:','["a map", "only a title", "a greeting, the reason for thanks and a closing", "a recipe"]'::jsonb,2,'Correspondence has a greeting, body and closing.','original'),
('128.5.b.12.D',2,'Which closing fits a friendly letter?','["Page two", "Chapter one", "The end", "Your friend, Ana"]'::jsonb,3,'Letters end with a closing and signature.','original'),
('128.5.b.13.A',2,'Which is a good research question?','["How do bees make honey?", "Stop.", "Bees.", "Honey is yellow."]'::jsonb,0,'Research questions ask something that sources can answer.','original'),
('128.5.b.13.A',3,'A good inquiry question should be:','["already answered", "open enough to need research to answer", "unrelated to the topic", "answerable with one word"]'::jsonb,1,'Good questions lead to investigation.','original'),
('128.5.b.13.B',3,'Following a research plan with adult assistance means you:','["let the adult research alone", "hide the plan", "work through your steps and check them with an adult", "skip the steps"]'::jsonb,2,'A plan guides steps and adult help keeps you on track.','original'),
('128.5.b.13.B',3,'Which belongs in a research plan?','["a recipe", "a cartoon", "a list of favorite colors", "a list of questions, sources and a due date"]'::jsonb,3,'Plans list what to ask, where to look and when.','original'),
('128.5.b.13.C',3,'A variety of sources includes:','["books, websites and interviews", "only your guess", "only a rumor", "only one book"]'::jsonb,0,'Using several kinds of sources makes research stronger.','original'),
('128.5.b.13.C',3,'To gather relevant information you should:','["use facts about other topics", "choose facts that answer your research question", "skip all sources", "copy every page"]'::jsonb,1,'Relevant facts match the question.','original'),
('128.5.b.13.D',3,'A diary written by a soldier during a war is a:','["secondary source", "index", "primary source", "glossary"]'::jsonb,2,'A first-hand record from the time is primary.','original'),
('128.5.b.13.D',3,'A textbook that summarizes a war years later is a:','["photograph from that day", "diary entry", "primary source", "secondary source"]'::jsonb,3,'Secondary sources are written after the event by someone not there.','original'),
('128.5.b.13.E',3,'To show understanding of gathered information you can:','["explain it in your own words", "copy it exactly", "hide it", "count the letters"]'::jsonb,0,'Restating shows understanding.','original'),
('128.5.b.13.E',3,'Which is the best way to show you understood an article?','["Count the words.", "Write a summary using key facts.", "Leave it blank.", "Copy the title."]'::jsonb,1,'A summary shows that you grasped the main points.','original'),
('128.5.b.13.F',3,'Paraphrasing means:','["skipping sources", "copying and saying it is yours", "restating ideas in your own words and naming the source", "changing one word only"]'::jsonb,2,'Paraphrasing is allowed when the source is credited.','original'),
('128.5.b.13.F',3,'Copying someone''s words without giving credit is:','["paraphrasing", "summarizing", "citing", "plagiarism"]'::jsonb,3,'Plagiarism is using others'' work as your own.','original'),
('128.5.b.13.G',3,'A works cited page lists:','["the sources you used", "your grades", "unused ideas", "your favorite books"]'::jsonb,0,'It gives credit to the sources.','original'),
('128.5.b.13.G',3,'A works cited entry usually begins with the:','["your name", "author''s name", "page color", "today''s weather"]'::jsonb,1,'Most entries start with the author.','original'),
('128.5.b.13.H',2,'Presenting research with a poster and a talk uses:','["no delivery", "a hidden draft", "a multimodal delivery", "a silent report only"]'::jsonb,2,'Mixing written and oral modes is multimodal.','original'),
('128.5.b.13.H',2,'Which is an oral way to present results?','["writing a letter", "drawing a silent map", "printing a list", "giving a short speech"]'::jsonb,3,'Oral delivery is spoken.','original'),
('128.5.b.2.A.i',3,'Which word has a written accent mark (an orthographic accent)?','["teléfono", "casa", "libro", "mesa"]'::jsonb,0,'Teléfono is stressed on the third-to-last syllable and carries an accent.','original'),
('128.5.b.2.A.i',3,'In the word café, the stress falls on the:','["middle of a letter", "last syllable", "no syllable", "first syllable"]'::jsonb,1,'The accent mark is over the last vowel, so it is stressed.','original'),
('128.5.b.2.A.ii',3,'Which letter makes the /s/ sound in the word cena?','["the letter h", "the letter q", "the letter c", "the letter k"]'::jsonb,2,'C before e or i can sound like s.','original'),
('128.5.b.2.A.ii',3,'Which word starts with the /k/ sound?','["sopa", "cielo", "zapato", "queso"]'::jsonb,3,'Qu before e makes the /k/ sound.','original'),
('128.5.b.2.A.iii',3,'Which word begins with a silent letter?','["hermano", "tío", "rana", "mano"]'::jsonb,0,'The letter h is silent in Spanish.','original'),
('128.5.b.2.A.iii',3,'In the word guitarra, how is the u treated?','["It sounds like b.", "It is silent.", "It sounds like f.", "It sounds like w."]'::jsonb,1,'In gui the u is silent.','original'),
('128.5.b.2.A.iv',3,'In which word do two vowels share one syllable?','["feo", "leer", "ciudad", "país"]'::jsonb,2,'Ciudad has the diphthong iu in one syllable.','original'),
('128.5.b.2.A.iv',3,'A strong vowel next to another strong vowel forms:','["a prefix", "a diphthong", "a digraph", "a hiatus"]'::jsonb,3,'Two strong vowels are pronounced in separate syllables.','original'),
('128.5.b.2.A.v',3,'Sí, quiero helado means:','["Yes, I want ice cream.", "No ice cream for me.", "Whether I want ice cream.", "If I want ice cream."]'::jsonb,0,'Sí with an accent means yes.','original'),
('128.5.b.2.A.v',3,'Why are mas and más spelled differently?','["Más is shorter.", "The accent shows a different meaning, but versus more.", "Accents are only decoration.", "They are the same word."]'::jsonb,1,'A diacritical accent separates words that sound alike.','original'),
('128.5.b.2.A.vi',3,'The prefix des- in deshacer means:','["again", "before", "to undo", "very"]'::jsonb,2,'Des- reverses the action.','original'),
('128.5.b.2.A.vi',3,'The suffix -mente in rápidamente makes the word an:','["verb", "article", "noun", "adverb"]'::jsonb,3,'-mente forms adverbs of manner.','original'),
('128.5.b.2.B.i',3,'Which spelling needs a written accent because it ends in n and is stressed on the last syllable?','["camión", "cámion", "camíon", "camion"]'::jsonb,0,'Agudas ending in n, s or a vowel take an accent.','original'),
('128.5.b.2.B.i',3,'Which word is grave (stress on the next-to-last syllable) and needs no accent because it ends in a vowel?','["jamás", "mesa", "café", "sofá"]'::jsonb,1,'Graves ending in a vowel, n or s need no accent.','original'),
('128.5.b.2.B.ii',3,'Which spelling is correct for a word stressed on the third-to-last syllable?','["pajarô", "pajaro", "pájaro", "pajáro"]'::jsonb,2,'Esdrújulas always carry a written accent.','original'),
('128.5.b.2.B.ii',3,'Palabras esdrújulas, like música, are words that:','["end only in n or s", "never carry a written accent", "are stressed on the last syllable", "always carry a written accent"]'::jsonb,3,'Stress on the antepenultimate syllable is always marked.','original'),
('128.5.b.2.B.iii',3,'Which spelling shows the hiatus in the word for a male relative, uncle?','["tío", "tîo", "tiyo", "tio"]'::jsonb,0,'The accent on í breaks the diphthong into a hiatus.','original'),
('128.5.b.2.B.iii',3,'In the word cuidado, the vowels ui:','["split into two syllables", "stay together in one syllable", "need an accent", "are silent"]'::jsonb,1,'Ui is a diphthong.','original'),
('128.5.b.2.B.iv',3,'Which question is written correctly?','["¿Donde vives?", "¿Dónde vives", "¿Dónde vives?", "Dónde vives?"]'::jsonb,2,'Question words carry accents and the question uses ¿ and ?.','original'),
('128.5.b.2.B.iv',3,'In ¿Cómo te llamas?, the word cómo has an accent because it:','["is a verb", "names a person", "ends the sentence", "asks a question"]'::jsonb,3,'Interrogatives carry a written accent.','original'),
('128.5.b.2.B.ix',3,'Which word begins with a hard r sound?','["rana", "pera", "toro", "caro"]'::jsonb,0,'R at the start of a word is trilled.','original'),
('128.5.b.2.B.ix',3,'Between two vowels, the strong trilled sound is spelled with:','["the letters rl", "a double letter rr", "a single letter r", "the letters rh"]'::jsonb,1,'Perro uses rr for the strong sound.','original'),
('128.5.b.2.B.v',3,'Which spelling means ''I know''?','["sè", "se", "sé", "sê"]'::jsonb,2,'Sé with an accent is the verb saber.','original'),
('128.5.b.2.B.v',3,'In Spanish, the pronoun meaning ''he'' is spelled:','["el", "ël", "èl", "él"]'::jsonb,3,'The accent separates él from the article el.','original'),
('128.5.b.2.B.vi',3,'Which spelling is correct for ''he ate'' (comer, simple past)?','["comió", "comio", "comiô", "cómio"]'::jsonb,0,'Simple past forms ending in a stressed vowel take an accent.','original'),
('128.5.b.2.B.vi',4,'Which spelling is correct for ''we used to sing'' in the imperfect past?','["cantabamos", "cantábamos", "cántabamos", "cantabámos"]'::jsonb,1,'Nosotros imperfect forms of -ar verbs take an accent on the á.','original'),
('128.5.b.2.B.vii',3,'Which spelling has the /ge/ sound correctly?','["gerra", "juerra", "guerra", "guerrra"]'::jsonb,2,'Gue has a silent u to keep the hard g.','original'),
('128.5.b.2.B.viii',3,'Which spelling names a road in a town?','["calye", "caye", "cayle", "calle"]'::jsonb,3,'Calle is spelled with ll.','original'),
('128.5.b.2.B.viii',3,'Which spelling names the yolk of an egg?','["yema", "iema", "jema", "llema"]'::jsonb,0,'Yema begins with y.','original'),
('128.5.b.2.B.x',3,'Which spelling of the word for ''also'' follows the rule of m before b?','["tamvién", "también", "tanbién", "tanvién"]'::jsonb,1,'Use m before b.','original')
